INSERT INTO restaurants (id, name, badge, image, tag, cuisine, hours_label, price_label, setting_label, about, detail, menu_pdf, sort_order) VALUES ('palmiste', 'Le Palmiste', 'CAFÉ · COFFEE & PASTRIES', '/images/palmiste-cappuccino-croissant.webp', 'A relaxing café stop for coffee, pastries and freshly baked bread.', 'Café', 'Daily · 09:00 – 17:30', 'Café prices, pay at the counter', 'Café terrace inside the park', 'A classic café serving hot and cold drinks, pastries and freshly baked bread, with cakes, sandwiches, bubble teas and our signature Arabian coffee. Unwind in the calm of the terrace, and say hello to Souris, our friendly domesticated deer.', 'Open every day 09:00 – 17:30 · 30 seats · hot and cold drinks, pastries, cakes and sandwiches.', '', 3) ON CONFLICT (id) DO NOTHING;
