-- 035: the owner's rebranding photo stock (November 2026). The riverside restaurant listed as
-- "La Citronelle" is La Bigarade (its menu PDF, the park factsheet and the photo folders all say so; the id
-- and URL stay /dine/citronelle). Adds Le Palmiste café, and new photos in the activity and restaurant galleries.
-- Idempotent: safe to run on every api pre-deploy (scripts/db-init.js).

UPDATE restaurants SET name = 'La Bigarade', badge = 'RIVERSIDE · EVENTS TO 400', image = '/images/bigarade-interior.webp', tag = 'Indian and Mauritian cuisine beside a quiet river.', cuisine = 'Indian & Mauritian', hours_label = '11:30 – 16:30 · not open every day', price_label = 'À la carte from Rs 400', setting_label = 'Riverside, near the entrance', about = 'An à la carte menu with a focus on Indian cuisine, set against the backdrop of a serene river: thalis, curries, Mauritian favourites and pasta, with plenty for vegetarians. The pavilion is also a premium event space for weddings, corporate events and special gatherings of up to 400 guests.', detail = 'Thali from Rs 600 · pasta, fried rice and noodles from Rs 400 · vegetarian choices · events through the sales team.', updated_at = now() WHERE id = 'citronelle' AND name <> 'La Bigarade';
DELETE FROM restaurant_gallery WHERE restaurant_id = 'citronelle' AND NOT EXISTS (SELECT 1 FROM restaurant_gallery WHERE src = '/images/bigarade-interior.webp');
UPDATE map_pins SET name = 'La Bigarade', sub = 'Indian and Mauritian cuisine beside a quiet river. Events up to 400 guests.', image = '/images/bigarade-interior.webp' WHERE go_target = 'citronelle' AND name <> 'La Bigarade';


